<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';
try{$uid=(int)requireAuth()->id;$type=strtoupper(trim((string)($_GET['entity_type']??'')));$entityId=(int)($_GET['entity_id']??0);$c=db();requirePermission($c,$uid,'reports.view');$s=$c->prepare('SELECT e.id,e.entity_type,e.entity_id,e.action,e.note,e.actor_id,e.actor_role,u.email actor_email,e.previous_event_hash,e.event_hash,e.created_at FROM erp_accountant_review_events e LEFT JOIN users u ON u.id=e.actor_id WHERE e.user_id=? AND e.entity_type=? AND e.entity_id=? ORDER BY e.id');$s->bind_param('isi',$uid,$type,$entityId);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();jsonResponse(['success'=>true,'data'=>$rows]);}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>$e->getMessage()],400);}
